		Zero2 <= Zero1;
		end
	end

	always@(reset)
	begin
		if(reset == 1'b1)
		begin
			PC_sum2 <= 0;
			ALUResult2 <= 0;
			ReadData2out <= 0;
			Branch2 <= 0;
			MemtoReg2 <= 0;
			MemWrite2 <= 0;
			MemRead2 <= 0;
