  reg QZ_r; 
  initial begin 
  QZ_r = 1'b0; 
  end 
  assign QZ = QZ_r; 
  assign TAP1 = TAS1 ? ~TA1 : TA1; 
  assign TAP2 = TAS2 ? ~TA2 : TA2; 
  assign TBP1 = TBS1 ? ~TB1 : TB1; 
  assign TBP2 = TBS2 ? ~TB2 : TB2; 
  assign BAP1 = BAS1 ? ~BA1 : BA1; 
  assign BAP2 = BAS2 ? ~BA2 : BA2; 
  assign BBP1 = BBS1 ? ~BB1 : BB1; 
  assign BBP2 = BBS2 ? ~BB2 : BB2; 
